body:
### Tested versions

Reproducible in c3e6b2

### System information

Windows 11 - Godot [master]

### Issue description

While testing Triangulate::is_inside_triangle(), I noticed several cases where the function returns unexpected results.

The function appears to:

1. Return incorrect results for points located exactly on an edge or vertex when include_edges=true.
2. Produce different results depending on whether the triangle vertices are provided in counter-clockwise (CCW) or clockwise (CW) order.
3. Incorrectly classify interior points for CW triangles.

### Steps to reproduce

Minimal reproduction:

```cpp
#include <core/math/triangulate.h>
#include <iostream>

int main(int argc, char** argv) {

   std::cout << "--- CCW ----" << std::endl;)
    {
        real_t Ax = 0;
        real_t Ay = 0;
        real_t Bx = 10;
        real_t By = 0;
        real_t Cx = 0;
        real_t Cy = 10;

        real_t Px = 2;
        real_t Py = 2;

        if (Triangulate::is_inside_triangle(Ax, Ay, Bx, By, Cx, Cy, Px, Py, true) != true) {
            std::cout << "Point is in triangle (with edges) : [FAILED]" << std::endl;
        }

        if (Triangulate::is_inside_triangle(Ax, Ay, Bx, By, Cx, Cy, Px, Py, false) != true) {
            std::cout << "Point is in triangle (without edges) : [FAILED]" << std::endl;
        }

        Px = 5;
        Py = 0;

        if (Triangulate::is_inside_triangle(Ax, Ay, Bx, By, Cx, Cy, Px, Py, true) != true) {
            std::cout << "Point is on edge AB (with edges) : [FAILED]" << std::endl;
        }

        if (Triangulate::is_inside_triangle(Ax, Ay, Bx, By, Cx, Cy, Px, Py, false) != false) {
            std::cout << "Point is on edge AB (without edges) : [FAILED]" << std::endl;
        }

        Px = 0;
        Py = 0;

        if (Triangulate::is_inside_triangle(Ax, Ay, Bx, By, Cx, Cy, Px, Py, true) != true) {
            std::cout << "Point is on vertex (with edges) : [FAILED]" << std::endl;
        }

        if (Triangulate::is_inside_triangle(Ax, Ay, Bx, By, Cx, Cy, Px, Py, false) != false) {
            std::cout << "Point is on vertex (without edges) : [FAILED]" << std::endl;
        }

        Px = 20;
        Py = 20;

        if (Triangulate::is_inside_triangle(Ax, Ay, Bx, By, Cx, Cy, Px, Py, true) != false) {
            std::cout << "Point is outside (with edges) : [FAILED]" << std::endl;
        }

        if (Triangulate::is_inside_triangle(Ax, Ay, Bx, By, Cx, Cy, Px, Py, false) != false) {
            std::cout << "Point is outside (without edges) : [FAILED]" << std::endl;
        }
    }

    std::cout << "--- CW ----" << std::endl;
    {
        real_t Ax = 0;
        real_t Ay = 0;
        real_t Bx = 0;
        real_t By = 10;
        real_t Cx = 10;
        real_t Cy = 0;

        real_t Px = 2;
        real_t Py = 2;

        if (Triangulate::is_inside_triangle(Ax, Ay, Bx, By, Cx, Cy, Px, Py, true) != true) {
            std::cout << "Point is in triangle(with edges) : [FAILED]" << std::endl;
        }

        if (Triangulate::is_inside_triangle(Ax, Ay, Bx, By, Cx, Cy, Px, Py, false) != true) {
            std::cout << "Point is in triangle (without edges) : [FAILED]" << std::endl;
        }

        Px = 5;
        Py = 0;

        if (Triangulate::is_inside_triangle(Ax, Ay, Bx, By, Cx, Cy, Px, Py, true) != true) {
            std::cout << "Point is on edge AB (with edges) : [FAILED]" << std::endl;
        }

        if (Triangulate::is_inside_triangle(Ax, Ay, Bx, By, Cx, Cy, Px, Py, false) != false) {
            std::cout << "Point is on edge AB (without edges) : [FAILED]" << std::endl;
        }

        Px = 0;
        Py = 0;

        if (Triangulate::is_inside_triangle(Ax, Ay, Bx, By, Cx, Cy, Px, Py, true) != true) {
            std::cout << "Point is on vertex (with edges) : [FAILED]" << std::endl;
        }

        if (Triangulate::is_inside_triangle(Ax, Ay, Bx, By, Cx, Cy, Px, Py, false) != false) {
            std::cout << "Point is on vertex (without edges) : [FAILED]" << std::endl;
        }

        Px = 20;
        Py = 20;

        if (Triangulate::is_inside_triangle(Ax, Ay, Bx, By, Cx, Cy, Px, Py, true) != false) {
            std::cout << "Point is outside (with edges) : [FAILED]" << std::endl;
        }

        if (Triangulate::is_inside_triangle(Ax, Ay, Bx, By, Cx, Cy, Px, Py, false) != false) {
            std::cout << "Point is outside (without edges) : [FAILED]" << std::endl;
        }
    }

    return 0;
}
```

Resulting in:

--- CCW ----
Point is on edge AB (with edges) : [FAILED]
Point is on edge AB (without edges) : [FAILED]
Point is on vertex (with edges) : [FAILED]
Point is on vertex (without edges) : [FAILED]

--- CW ----
Point is in triangle(with edges) : [FAILED]
Point is in triangle (without edges) : [FAILED]
Point is on edge AB (with edges) : [FAILED]
Point is on vertex (with edges) : [FAILED]

